/**
 * Sidebar Entry Point for Extension
 * Loads AppSidebar component in extension context
 */

import React from 'react'
import { createRoot } from 'react-dom/client'
import AppSidebar from '@/components/app-sidebar'
import { Providers } from '@/app/providers'
import { ThemeProvider } from '@/components/theme-provider'
import { SidebarProvider } from '@/components/ui/sidebar'
import '@/app/globals.css'

// Sidebar-specific initialization
function SidebarApp() {
  const [mounted, setMounted] = React.useState(false)

  React.useEffect(() => {
    setMounted(true)
  }, [])

  if (!mounted) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
          <p className="text-muted-foreground">Loading Forkyy...</p>
        </div>
      </div>
    )
  }

  return (
    <Providers>
      <ThemeProvider
        attribute="class"
        defaultTheme="system"
        enableSystem
        disableTransitionOnChange
      >
        <SidebarProvider defaultOpen={true}>
          <AppSidebar />
        </SidebarProvider>
      </ThemeProvider>
    </Providers>
  )
}

// Initialize React app with error handling
try {
  const rootElement = document.getElementById('root')
  if (rootElement) {
    const root = createRoot(rootElement)
    root.render(<SidebarApp />)
    console.log('✅ Forkyy Sidebar React app initialized')
  } else {
    console.error('❌ Root element not found')
    document.body.innerHTML = '<div style="padding: 2rem; text-align: center;"><h1>Error</h1><p>Root element not found</p></div>'
  }
} catch (error) {
  console.error('❌ Failed to initialize Sidebar React app:', error)
  const rootElement = document.getElementById('root')
  if (rootElement) {
    rootElement.innerHTML = `
      <div style="padding: 2rem; text-align: center; font-family: system-ui;">
        <h1>Error Loading Sidebar</h1>
        <p>${error instanceof Error ? error.message : 'Unknown error'}</p>
        <p style="margin-top: 1rem; font-size: 0.9rem; color: #666;">
          Check the browser console (F12) for details.
        </p>
      </div>
    `
  }
}

